 10: @ObservedV2
 11: export default class OrderConfirmViewModel extends BaseNetWorkViewModel<ConfirmOrder> {
 12:   /**
 13:    * 订单缓存本地存储仓库
 14:    */
 15:   private readonly orderCacheStoreRepository: OrderCacheStoreRepository = new OrderCacheStoreRepository();
 16:   /**
 17:    * 页面仓库
 18:    */
 19:   private readonly pageRepository: PageRepository = new PageRepository();
 20:   /**
 21:    * 购物车仓库
 22:    */
 23:   private readonly cartRepository: CartRepository = new CartRepository();
 24:   /**
 25:    * 从购物车来的商品项（仅购物车页面会存储）
 26:    */
 27:   cachedCarts: Cart[] | null = null;
 28:   /**
 29:    * 选中的商品列表（从缓存中获取）
 30:    */
 31:   @Trace
 32:   selectedGoodsList: SelectedGoods[] = [];
 33:   /**
 34:    * 购物车列表（用于页面展示）
 35:    * 优先从 cachedCarts 获取，没有则从 selectedGoodsList 转换
 36:    */
 37:   @Trace
 38:   cartList: Cart[] = [];
 39:   /**
 40:    * 订单备注
 41:    */
 42:   @Trace
 43:   remark: string = "";
 44:   /**
 45:    * 优惠券弹出层的显示状态
 46:    */
 47:   @Trace
 48:   couponModalVisible: boolean = false;
 49:   /**
 50:    * 选中的优惠券
 51:    */
 52:   @Trace
 53:   selectedCoupon: Coupon | null = null;
 54:   /**
 55:    * 商品原价（单位：元）
 56:    */
 57:   @Trace
 58:   originalPrice: number = 0;
 59:   /**
 60:    * 优惠券折扣金额（单位：元）
 61:    */
 62:   @Trace
 63:   discountAmount: number = 0;
 64:   /**
 65:    * 最终价格（单位：元）
 66:    */
 67:   @Trace
 68:   totalPrice: number = 0;
 69: 
 70:   /**
 71:    * 请求确认订单页面数据
 72:    * @returns {Promise<NetworkResponse<ConfirmOrder>>} 确认订单页面数据
 73:    */
 74:   protected requestRepository(): Promise<NetworkResponse<ConfirmOrder>> {
 75:     return this.pageRepository.getConfirmOrder();
 76:   }
 77: 
 78:   /**
 79:    * 页面出现时加载数据
 80:    * @returns {void} 无返回值
 81:    */
 82:   aboutToAppear(): void {
 83:     // 先加载缓存数据
 84:     this.loadOrderCache();
 85:     // 再执行网络请求
 86:     super.aboutToAppear();
 87:   }
 88: 
 89:   /**
 90:    * 从缓存加载订单数据
 91:    * @returns {Promise<void>} Promise<void>
 92:    */
 93:   async loadOrderCache(): Promise<void> {
 94:     // 1. 读取购物车缓存（仅购物车页面会存储）
 95:     this.cachedCarts = await this.orderCacheStoreRepository.loadCarts();
 96: 
 97:     // 2. 读取已选商品列表
 98:     this.selectedGoodsList = await this.orderCacheStoreRepository.loadSelectedGoodsList() ?? [];
 99: 
100:     // 3. 购物车列表：优先从 cachedCarts 获取，没有则从 selectedGoodsList 转换
101:     if (this.cachedCarts && this.cachedCarts.length > 0) {
102:       this.cartList = this.cachedCarts;
103:     } else {
104:       this.cartList = this.convertSelectedGoodsToCartList(this.selectedGoodsList);
105:     }
106: 
107:     // 4. 清除缓存，避免重复使用
108:     await this.orderCacheStoreRepository.clearAll();
109: 
110:     // 5. 计算商品原价
111:     this.calculateOriginalPrice();
112:   }
113: 
114:   /**
115:    * 将已选商品列表转换为购物车列表
116:    * @param {SelectedGoods[]} goodsList 已选商品列表
117:    * @returns {Cart[]} 购物车列表
118:    */
119:   private convertSelectedGoodsToCartList(goodsList: SelectedGoods[]): Cart[] {
120:     // 按商品ID分组
121:     const groupedMap = new Map<number, SelectedGoods[]>();
122: 
123:     for (const goods of goodsList) {
124:       const existingList = groupedMap.get(goods.goodsId);
125:       if (existingList) {
126:         existingList.push(goods);
127:       } else {
128:         groupedMap.set(goods.goodsId, [goods]);
129:       }
130:     }
131: 
132:     // 为每个商品ID创建一个Cart对象
133:     const result: Cart[] = [];
134: 
135:     groupedMap.forEach((items: SelectedGoods[], goodsId: number) => {
136:       const firstItem = items[0];
137: 
138:       const cart = new Cart();
139:       cart.goodsId = goodsId;
140:       cart.goodsName = firstItem.goodsInfo?.title ?? "";
141:       cart.goodsMainPic = firstItem.goodsInfo?.mainPic ?? "";
142: 
143:       // 收集该商品的所有规格
144:       const allSpecs: CartGoodsSpec[] = [];
145: 
146:       for (const selectedItem of items) {
147:         // 如果有规格信息，转换为CartGoodsSpec并添加
148:         if (selectedItem.spec) {
149:           const cartSpec = new CartGoodsSpec();
150:           cartSpec.id = selectedItem.spec.id;
151:           cartSpec.goodsId = selectedItem.spec.goodsId;
152:           cartSpec.name = selectedItem.spec.name;
153:           cartSpec.price = selectedItem.spec.price;
154:           cartSpec.stock = selectedItem.spec.stock;
155:           cartSpec.count = selectedItem.count;
156:           cartSpec.images = selectedItem.spec.images;
157:           allSpecs.push(cartSpec);
158:         }
159:       }
160: 
161:       cart.spec = allSpecs;
162:       result.push(cart);
163:     });
164: 
165:     return result;
166:   }
167: 
168:   /**
169:    * 是否从购物车来的
170:    * @returns {boolean} 是否从购物车来
171:    */
172:   get isFromCart(): boolean {
173:     return this.cachedCarts !== null && this.cachedCarts.length > 0;
174:   }
175: 
