196:    */
197:   showCouponModal(): void {
198:     this.couponModalVisible = true;
199:   }
200: 
201:   /**
202:    * 隐藏优惠券弹出层
203:    * @returns {void} 无返回值
204:    */
205:   hideCouponModal(): void {
206:     this.couponModalVisible = false;
207:   }
208: 
209:   /**
210:    * 选择优惠券
211:    * @param {Coupon | null} coupon 选中的优惠券，null表示不使用优惠券
212:    * @returns {void} 无返回值
213:    */
214:   selectCoupon(coupon: Coupon | null): void {
215:     this.selectedCoupon = coupon;
216:     this.hideCouponModal();
217:     this.calculatePrices();
218:   }
219: 
220:   /**
221:    * 计算商品原价
222:    * @returns {void} 无返回值
223:    */
224:   private calculateOriginalPrice(): void {
225:     let price = 0;
226:     for (const cart of this.cartList) {
227:       for (const spec of cart.spec) {
228:         price += spec.price * spec.count;
229:       }
230:     }
231:     this.originalPrice = price;
232:     this.calculatePrices();
233:   }
234: 
235:   /**
236:    * 计算价格（包括优惠券折扣）
237:    * @returns {void} 无返回值
238:    */
239:   private calculatePrices(): void {
240:     let discountValue = 0;
241: 
242:     if (this.selectedCoupon && this.selectedCoupon.condition) {
243:       // 检查是否满足使用条件
244:       if (this.originalPrice >= this.selectedCoupon.condition.fullAmount) {
245:         discountValue = this.selectedCoupon.amount ?? 0;
246:       }
247:     }
248: 
249:     this.discountAmount = discountValue;
250:     this.totalPrice = Math.max(this.originalPrice - discountValue, 0);
251:   }
