  48:       title: $r("app.string.cart"),
  49:       viewModel: this.vm,
  50:       menus: this.vm.isEmpty ? [] : [
  51:         {
  52:           value: "",
  53:           icon: this.vm.isEditing
  54:             ? $r("app.media.ic_success")
  55:             : $r("app.media.ic_edit"),
  56:           action: (): void => {
  57:             this.vm.toggleEditMode();
  58:           }
  59:         }
  60:       ],
  61:       paddingValue: {
  62:         top: this.windowSafeAreaState.topInset,
  63:         left: this.windowSafeAreaState.leftInset,
  64:         right: this.windowSafeAreaState.rightInset
  65:       },
  66:     }) {
  67:       ColumnStart({ fillMaxSize: true }) {
  68:         this.CartContent();
  69:         if (!this.vm.isEmpty) {
  70:           CartBottomBar({
  71:             safeAreaEnabled: false,
  72:             isAllSelected: this.vm.isAllSelected,
  73:             isEditing: this.vm.isEditing,
  74:             selectedCount: this.vm.selectedCount,
  75:             totalAmount: this.vm.totalAmount,
  76:             onToggleSelectAll: (): void => {
  77:               this.vm.toggleSelectAll();
  78:             },
  79:             onDeleteClick: (): void => {
  80:               this.vm.deleteSelected();
  81:             },
  82:             onSettleClick: (): void => {
  83:               this.vm.onSettleClick();
  84:             },
  85:             windowSafeAreaState: this.windowSafeAreaState
  86:           });
  87:         }
  88:       }
