 100:     } else {
 101:       List({ space: 12 }) {
 102:         // 空的 ListItem 用于分隔购物车商品和底部栏
 103:         ListItem() {
 104:         }
 105: 
 106:         ForEach(this.vm.cartList, (cart: Cart) => {
 107:           ListItem() {
 108:             OrderGoodsCard({
 109:               data: cart,
 110:               onGoodsClick: (goodsId: number): void => {
 111:                 GoodsNavigator.toDetail(goodsId);
 112:               },
 113:               onQuantityChanged: (specId: number, count: number): void => {
 114:                 this.vm.updateSpecCount(cart.goodsId, specId, count);
 115:               },
 116:               enableQuantityStepper: true,
 117:               itemSelectSlotBuilder: (spec: CartGoodsSpec): void => {
 118:                 this.CheckboxSlot(cart.goodsId, spec);
 119:               }
 120:             });
 121:           }
 122:         }, (cart: Cart): string => JSON.stringify(cart));
 123:         ListItem() {
 124:         }
 125:       }
 126:       .width(P100)
 127:       .padding({
 128:         left: $r("app.float.space_horizontal_medium"),
 129:         right: $r("app.float.space_horizontal_medium"),
 130:       })
 131:       .layoutWeight(1)
 132: 
 133:       .scrollBar(BarState.Off);
 134:     }
 135:   }
 136: 
 137:   /**
 138:    * 选择框插槽
