  11:   /**
  12:    * 当前网络请求 UI 状态
  13:    */
  14:   @Param
  15:   uiState: BaseNetWorkUiState = BaseNetWorkUiState.LOADING;
  16:   /**
  17:    * 错误状态下的重试回调
  18:    */
  19:   @Param
  20:   onRetry: () => void = () => {
  21:   };
  22:   /**
  23:    * 自定义加载内容
  24:    */
  25:   @BuilderParam
  26:   loadingBuilder: CustomBuilder;
  27:   /**
  28:    * 自定义错误内容
  29:    */
  30:   @BuilderParam
  31:   errorBuilder: CustomBuilder;
  32:   /**
  33:    * 成功状态下渲染内容
  34:    */
  35:   @BuilderParam
  36:   content: CustomBuilder;
  37: 
  38:   /**
  39:    * 默认加载视图
  40:    * @returns {void} 无返回值
  41:    */
  42:   @Builder
  43:   buildDefaultLoading(): void {
  44:     PageLoading();
  45:   }
  46: 
  47:   /**
  48:    * 默认错误视图
  49:    * @returns {void} 无返回值
  50:    */
  51:   @Builder
  52:   buildDefaultError(): void {
  53:     EmptyNetwork({
  54:       onAction: this.onRetry
  55:     });
  56:   }
  57: 
  58:   /**
  59:    * 渲染网络请求状态视图
  60:    * @returns {void} 无返回值
  61:    */
  62:   build() {
  63:     Column() {
  64:       if (this.uiState === BaseNetWorkUiState.LOADING) {
  65:         Column() {
  66:           if (this.loadingBuilder) {
  67:             this.loadingBuilder();
  68:           } else {
  69:             this.buildDefaultLoading();
  70:           }
  71:         }
  72:         .transition(TransitionEffect.OPACITY.animation({ duration: 300, curve: Curve.EaseInOut }))
  73:       } else if (this.uiState === BaseNetWorkUiState.ERROR) {
  74:         Column() {
  75:           if (this.errorBuilder) {
  76:             this.errorBuilder();
  77:           } else {
  78:             this.buildDefaultError();
  79:           }
  80:         }
  81:         .transition(TransitionEffect.OPACITY.animation({ duration: 300, curve: Curve.EaseInOut }))
  82:       } else {
  83:         Column() {
  84:           if (this.content) {
  85:             this.content();
  86:           }
  87:         }
  88:         .transition(TransitionEffect.OPACITY.animation({ duration: 300, curve: Curve.EaseInOut }))
  89:       }
  90:     }
  91:   }
  92: }
