import { getHostCtx } from "util";
import { NavigationHost } from "../navigation/NavigationHost";
import EntryViewModel from "../viewmodel/EntryViewModel";

/**
 * @file 应用首页，挂载全局 NavigationHost
 * @author Joker.X
 */
@Entry
@ComponentV2
struct EntryPage {
  @Local vm: EntryViewModel = new EntryViewModel();

  /**
   * 初始化入口逻辑
   * @returns {void} 无返回值
   */
  aboutToAppear(): void {
    const hostContext = getHostCtx(this);
    if (!hostContext) {
      console.error("[EntryPage] Failed to obtain host context.");
      return;
    }
    this.vm.aboutToAppear(hostContext);
  }

  /**
   * 释放入口资源
   * @returns {void} 无返回值
   */
  aboutToDisappear(): void {
    this.vm.aboutToDisappear();
  }

  /**
   * 渲染根导航容器
   * @returns {void} 无返回值
   */
  build() {
    Column() {
      NavigationHost()
    }
  }
}

import { MainPage } from 'main';
import { RouteBuild, NAV_PATH_STACK_KEY, setNavPathStack } from 'navigation';

/**
 * @file 挂载全局导航栈
 * @author Joker.X
 */
@ComponentV2
export struct NavigationHost {
  /**
   * 导航栈
   */
  @Provider(NAV_PATH_STACK_KEY)
  navPathStack: NavPathStack = new NavPathStack();

  aboutToAppear(): void {
    setNavPathStack(this.navPathStack);
  }

  /**
   * 导航目标构建器
   * @param name 路由名称
   * @returns 路由构建器
   */
  @Builder
  PagesMap(name: string) {
    if (RouteBuild.getBuilder(name) !== undefined) {
      (RouteBuild.getBuilder(name) as WrappedBuilder<[]>).builder();
    }
  }

  /**
   * 导航目标构建器
   * @returns 路由构建器
   */
  build() {
    Navigation(this.navPathStack) {
      MainPage()
    }
    .hideTitleBar(true)
    .mode(NavigationMode.Stack)
    .navDestination(this.PagesMap)
  }
}

/**
